 			"Years of Renewal : " + @Text(NoOfYears) + @NewLine +
			"Date Applied : " + @Text(DateApplied) +  @NewLine +
			"Sticker Mode : " + @Text(Sticker) + @NewLine +
			"Permit No. :  " + @Text(WorkPermitNo) + @NewLine +
			"Contract Period : From "  + @Text(ContractPeriod) + " To "  + @Text(ContractPeriod_1) + @NewLine +
			"New Expiry Date : " + @Text(WorkPermitExpiryDate) + @NewLine +
			"Send To : " + @Name([CN];SendTo) + @NewLine +
			"CC : " + @Name([CN];CC) + @NewLine +
