FIELD DateSubmitted := @Now;

@MailSend(SendTo1;CC1;NULL;"Foreign Workers Permit to Work - Renewed : " + EmpNo + " - " + Name  ;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

