strServer := @Subset(@DbName; 1);
strDatabase:= "Current/PeopleNames.nsf";
strView:= "($VIMGroups)";
strGroupName := "ISADMIN";
@DbLookup("":"NoCache";strServer:strDatabase; strView; strGroupName  ; 3 ; [FailSilent])

@Command([EditDocument];"1");

@If (Name= ""; @Return(@Do(@Command([EditGotoField];"Name") ;@Prompt([Ok];"Missing Value"; "Please state the Name!")));"");
@If (EmpNo= ""; @Return(@Do(@Command([EditGotoField];"EmpNo") ;@Prompt([Ok];"Missing Value"; "Please state the Employee No.!")));"");
@If (Department= ""; @Return(@Do(@Command([EditGotoField];"Department") ;@Prompt([Ok];"Missing Value"; "Please select the Department!")));"");
@If (Hostel= ""; @Return(@Do(@Command([EditGotoField];"Hostel") ;@Prompt([Ok];"Missing Value"; "Please state the hostel address!")));"");
@If (DOB= ""; @Return(@Do(@Command([EditGotoField];"DOB") ;@Prompt([Ok];"Missing Value"; "Please insert the  Date of Birth!")));"");
@If (DOC= ""; @Return(@Do(@Command([EditGotoField];"DOC") ;@Prompt([Ok];"Missing Value"; "Please insert the  Date of Commencement!")));"");
@If (PassportNoNew= ""; @Return(@Do(@Command([EditGotoField];"PassportNoNew") ;@Prompt([Ok];"Missing Value"; "Please state new passport no.!")));"");
@If (PassportExpiryDate= ""; @Return(@Do(@Command([EditGotoField];"PassportExpiryDate") ;@Prompt([Ok];"Missing Value"; "Please select the Passport Expiry Date!")));"");
@If (WorkPermitExpiryDate= ""; @Return(@Do(@Command([EditGotoField];"WorkPermitExpiryDate") ;@Prompt([Ok];"Missing Value"; "Please insert your Date of Expiry!")));"");

FIELD ModName := @V3UserName;
FIELD ModDate := @Now;
FIELD CurrentAction := "Submitted";

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

