SELECT Form="Hostel Certification" & (
RD_1_1=@Today | RD_2_1=@Today | RD_3_1=@Today | RD_4_1=@Today | RD_5_1=@Today | RD_6_1=@Today | RD_7_1=@Today | RD_8_1=@Today | RD_9_1=@Today | RD_10_1=@Today |
@Today=@Adjust(RD_1_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_2_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_3_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_4_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_5_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_6_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_7_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_8_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_9_1;-1;0;0;0;0;0) | @Today=@Adjust(RD_10_1;-1;0;0;0;0;0)
)

